from hourglass.models import Span
from hourglass.parsing import format_clock


def _snap(minutes, step):
    return (minutes + step // 2) // step * step


# ---
def round_spans(spans, step):
    if step <= 0 or 60 % step:
        raise ValueError(
            "step must divide an hour evenly: {}".format(step)
        )
    labels = []
    for span in spans:
        start = _snap(span.start, step)
        end = _snap(span.end, step)
        hours, minutes = divmod(Span(start, end).minutes, 60)
        labels.append(
            "{}-{} ({}h {}m)".format(
                format_clock(start), format_clock(end), hours, minutes
            )
        )
    return labels
