cat > tests/test_rounding.py <<'EOF'
import unittest

from hourglass.models import Span
from hourglass.rounding import round_spans


class RoundSpansTests(unittest.TestCase):
    def test_label_after_rounding(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 12)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_several_spans(self):
        spans = [Span(0, 60), Span(61, 100)]
        self.assertEqual(
            round_spans(spans, 5),
            ["00:00-01:00 (1h 0m)", "01:00-01:40 (0h 40m)"],
        )

    def test_bad_steps(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
